def max_consecutive_good_days(projected_sales, k):
  l, r = 0, 0
  window_bad_days = 0
  cur_max = 0
  while r < len(projected_sales):
    can_grow = projected_sales[r] >= 10 or window_bad_days < k
    if can_grow:
      if projected_sales[r] < 10:
        window_bad_days += 1
      r += 1
      cur_max = max(cur_max, r - l)
    else:
      if projected_sales[l] < 10:
        window_bad_days -= 1
      l += 1
  return cur_max

