function maxConsecutiveGoodDays(projectedSales, k) {
  let l = 0,
    r = 0;
  let windowBadDays = 0;
  let curMax = 0;
  while (r < projectedSales.length) {
    const canGrow = projectedSales[r] >= 10 || windowBadDays < k;
    if (canGrow) {
      if (projectedSales[r] < 10) {
        windowBadDays++;
      }
      r++;
      curMax = Math.max(curMax, r - l);
    } else {
      if (projectedSales[l] < 10) {
        windowBadDays--;
      }
      l++;
    }
  }
  return curMax;
}

